import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parse.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0)), y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sorted = (t) => [...t.map.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  switch (n.t) {
    case 'string': return JSON.stringify(n.v)
    case 'integer': return n.v.toString()
    case 'float': return JSON.stringify(n.v)
    case 'boolean': return String(n.v)
    case 'array':
      if (!n.items.length) return '[]'
      return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
    default: {
      const ks = sorted(n)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.map.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
    }
  }
}

function keys(n, path, out) {
  if (n.t === 'table') {
    for (const k of sorted(n)) {
      const p = path === null ? k : path + '.' + k
      const c = n.map.get(k)
      out.push(p + ' ' + c.t)
      keys(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = path + '[' + i + ']'
      out.push(p + ' ' + c.t)
      keys(c, p, out)
    })
  }
}

let root
try {
  root = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write('error: ' + e.message + '\n')
  process.exit(2)
}
if (mode === 'json') process.stdout.write(toJson(root, 0) + '\n')
else {
  const out = []
  keys(root, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
EOF
